{
  "name": "AG-UC2 双轴压电步进控制器",
  "name_en": "AG-UC2 Two-Axis Piezo Stepper Controller",
  "manufacturer": "Newport",
  "description": "用于驱动 Newport Agilis 系列两轴压电步进位移台或微定位器的运动控制器。设备可控制 X/Y 两个轴，支持相对移动、连续点动、限位搜索和状态查询，常用于光学对准、精密位移和微定位实验。",
  "description_en": "A motion controller for Newport Agilis two-axis piezo stepper stages or micropositioners. It controls X and Y axes and supports relative motion, continuous jogging, limit seeking, and status monitoring, making it suitable for optical alignment, precision positioning, and micromanipulation experiments.",
  "tag_hints": [
    "piezo stepper control",
    "two-axis positioning",
    "micropositioning",
    "optical alignment",
    "serial motion controller",
    "limit switch sensing"
  ],
  "actions": [
    {
      "action_name": "auto-ag_query",
      "description": "向控制器发送原始查询命令并读取字符串响应",
      "description_en": "Send a raw query command to the controller and read the string response"
    },
    {
      "action_name": "auto-ag_sendcmd",
      "description": "向控制器发送原始命令",
      "description_en": "Send a raw command to the controller"
    },
    {
      "action_name": "auto-enable_remote_mode",
      "description": "获取/设置远程模式状态",
      "description_en": "Get/set remote mode status"
    },
    {
      "action_name": "auto-reset_controller",
      "description": "复位控制器并恢复临时设置为默认值",
      "description_en": "Reset the controller and restore temporary settings to their defaults"
    },
    {
      "action_name": "auto-sleep_time",
      "description": "获取/设置命令后的通信等待时间",
      "description_en": "Get/set the communication wait time after commands"
    },
    {
      "action_name": "auto-axis",
      "description": "获取指定轴通道",
      "description_en": "Get the selected axis channel"
    },
    {
      "action_name": "auto-error_previous_command",
      "description": "获取上一条命令的错误信息",
      "description_en": "Get the error information for the previous command"
    },
    {
      "action_name": "auto-firmware_version",
      "description": "获取固件版本",
      "description_en": "Get the firmware version"
    },
    {
      "action_name": "auto-limit_status",
      "description": "获取限位开关状态",
      "description_en": "Get the limit switch status"
    },
    {
      "action_name": "auto-axis_status",
      "description": "获取轴状态",
      "description_en": "Get the axis status"
    },
    {
      "action_name": "auto-jog",
      "description": "以指定点动模式连续运动选定轴",
      "description_en": "Continuously jog the selected axis in the specified jog mode"
    },
    {
      "action_name": "auto-number_of_steps",
      "description": "获取/设置选定轴的步数参数",
      "description_en": "Get/set the step count parameter for the selected axis"
    },
    {
      "action_name": "auto-move_relative",
      "description": "使选定轴按给定步数做相对移动",
      "description_en": "Move the selected axis by a specified number of steps"
    },
    {
      "action_name": "auto-move_to_limit",
      "description": "使选定轴移动到限位",
      "description_en": "Move the selected axis to a limit"
    },
    {
      "action_name": "auto-step_amplitude",
      "description": "获取/设置步进幅度",
      "description_en": "Get/set the step amplitude"
    },
    {
      "action_name": "auto-step_delay",
      "description": "获取/设置步进延时",
      "description_en": "Get/set the step delay"
    },
    {
      "action_name": "auto-am_i_still",
      "description": "获取轴是否仍在运动",
      "description_en": "Get whether the axis is still moving"
    },
    {
      "action_name": "auto-zero_position",
      "description": "将当前位置清零",
      "description_en": "Zero the current position reference"
    }
  ]
}

